export const permissionKey = (toolKey, mappingKey) => JSON.stringify([toolKey, mappingKey])

// The current static Catalog output is scoped to a whole tool. It cannot remove
// just one denied permission from the generated bytes (CatalogPreviewAssembler).
export const previewPolicies = option => (option.supportedPolicies || []).filter(policy => policy !== 'DENY')

export function defaultPermissionChoices(items) {
  return Object.fromEntries((items || []).flatMap(item => (item.permissionOptions || []).map(option => [
    permissionKey(item.toolKey, option.mappingKey), option.defaultPolicy,
  ])))
}

export function permissionSelections(items, selectedToolKeys, choices) {
  const selected = new Set(selectedToolKeys)
  if ([...selected].some(key => !(items || []).some(item => item.toolKey === key))) {
    throw new Error('추천에 없는 도구를 선택할 수 없습니다.')
  }
  return (items || []).filter(item => selected.has(item.toolKey)).flatMap(item =>
    (item.permissionOptions || []).map(option => {
      const policy = choices[permissionKey(item.toolKey, option.mappingKey)] ?? option.defaultPolicy
      if (policy === 'DENY') throw new Error('현재 설정 생성은 개별 권한 거부를 지원하지 않습니다. 도구를 제외해 주세요.')
      if (!option.supportedPolicies.includes(policy)) throw new Error('지원하지 않는 권한 선택입니다.')
      return { toolKey: item.toolKey, mappingKey: option.mappingKey, policy }
    }))
}
